  return { root, cpg, taint, ctx:{root, budgetTokens:10000} };
}
async function g(f){ const r=await f.cpg.invoke('cpg.build',{path:'src/a.js'},f.ctx); return JSON.parse(readFileSync(r.refs[0].path,'utf8')); }
function cfg(g){ return g.edges.filter(e=>e.type.startsWith('CFG_')).map(e=>{
  const n=id=>g.nodes.find(x=>x.id===id);
  const lab=id=>{ const x=n(id); if(!x) return id.includes(':exit')?':exit':id.includes(':entry')?':entry':id.slice(-12); return `${x.type}:${x.kind||''}@L${x.range?.start?.line||'?'}`; };
  return `${e.type} ${lab(e.from)} -> ${lab(e.to)}`;
}); }

const cases = [
  ['paren+comments true', `function readInput(){} function send(v){}\nfunction run(){ let value; if(/*l*/true/*t*/){ value=1 } else { value=readInput() } send(value) }\n`],
  ['double paren true', `function readInput(){} function send(v){}\nfunction run(){ let value; if(((true))){ value=1 } else { value=readInput() } send(value) }\n`],
  ['true no else', `function readInput(){} function send(v){}\nfunction run(){ let value; if(true){ value=1 } send(value) }\n`],
  ['false empty then join', `function readInput(){} function send(v){}\nfunction run(){ let value=0; if(false){} send(value) }\n`],
  ['nested paren comment false', `function readInput(){} function send(v){}\nfunction run(){ let value; if((/*c*/false)){ value=readInput() } send(value) }\n`],
];
for (const [name, src] of cases) {
  const f = fix(src);
  const graph = await g(f);
  const deadJoins = graph.edges.filter(e => ['CFG_NEXT','CFG_EXIT'].includes(e.type) && {
    const from = graph.nodes.find(n=>n.id===e.from);
    return from?.type==='statement' && from.cfgReachable===false;
  });
  // fix filter - can't do that way
}
// redo properly
for (const [name, src] of cases) {
  const f = fix(src);
  const graph = await g(f);
  const unreachable = new Set(graph.nodes.filter(n=>n.type==='statement'&&n.cfgReachable===false).map(n=>n.id));
  const deadOut = graph.edges.filter(e => ['CFG_NEXT','CFG_EXIT'].includes(e.type) && unreachable.has(e.from));
  const t = await f.taint.invoke('cpg.taint', {path:'src/a.js', sourceNames:['readInput'], sinkNames:['send'], depth:20}, f.ctx);
  console.log('===', name);
  console.log('paths', t.payload.length);
  console.log('deadOut', deadOut.length);
  console.log(cfg(graph).join('\n'));
  const stmts = graph.nodes.filter(n=>n.type==='statement').map(n=>`L${n.range.start.line} ${n.kind} reach=${n.cfgReachable}`);
  console.log(stmts.join(' | '));
}

// PS2 may-union at join with both arms defining
{
  const f = fix(`function run(flag){ let x=1; if(flag){ x=2 } else { x=3 } use(x) }\n`);
  const graph = await g(f);
  const use = graph.nodes.find(n=>n.type==='identifier'&&n.name==='x'&&n.role==='reference');
  const defs = graph.edges.filter(e=>e.type==='REACHING_DEF'&&e.to===use.id);
  console.log('=== join may-reach count', defs.length);
}

// parenthesized identifier not pruned
{
  const f = fix(`function readInput(){} function send(v){}\nfunction run(){ let value; if((flag)){ value=readInput() } send(value) }\n`);
  const t = await f.taint.invoke('cpg.taint', {path:'src/a.js', sourceNames:['readInput'], sinkNames:['send'], depth:20}, f.ctx);
  console.log('=== nonliteral paren paths', t.payload.length);
}

// schema version
{
  const f = fix(`function run(){ if(true){ a() } else { b() } }\n`);
  const graph = await g(f);
  console.log('schema', graph.schemaVersion, 'literal edges false present?', graph.edges.some(e=>e.type==='CFG_FALSE'));
}

// delta inherits REACHING_DEF - smoke
import { AtlasCpgDelta } from './impl/src/index.mjs';
{
  const root = mkdtempSync(join(tmpdir(), 'r-'));
  const art = mkdtempSync(join(tmpdir(), 'a-'));
  mkdirSync(join(root,'src'),{recursive:true});
  writeFileSync(join(root,'src/a.js'), 'function run(flag){ let v=1; if(flag){ v=2 } use(v) }\n');
  writeFileSync(join(root,'src/b.js'), 'function run(flag){ let v=1; if(flag){ v=2 } else { v=3 } use(v) }\n');
  const d = new AtlasCpgDelta({ artifactRoot: art, maxSourceBytes:64*1024, maxGraphBytes:512*1024, maxDeltaBytes:512*1024, maxReachDefPairs:128 });
  const r = await d.invoke('cpg.delta', { beforePath:'src/a.js', afterPath:'src/b.js' }, { root, budgetTokens:10000 });
  console.log('delta status', r.status, 'meaning', r.provenance?.meaning, Object.keys(r.provenance||{}));
}
EOF

